node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Start a transaction for atomicity
const cancel = db.transaction(() => {
  // 1. Update order status and cancel reason
  const updateOrder = db.prepare(\`
    UPDATE orders 
    SET status = 'cancelled', 
        cancel_reason = 'no longer needed'
    WHERE order_id = 'ORD-E0E671'
  \`);
  const orderResult = updateOrder.run();
  console.log('Order updated:', orderResult.changes, 'row(s)');

  // 2. Update order items status to cancelled
  const updateItems = db.prepare(\`
    UPDATE order_items 
    SET item_status = 'cancelled'
    WHERE order_id = 'ORD-E0E671'
  \`);
  const itemsResult = updateItems.run();
  console.log('Order items updated:', itemsResult.changes, 'row(s)');

  // 3. Add refund entry to order_payments
  const insertRefund = db.prepare(\`
    INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id, created_at)
    VALUES ('ORD-E0E671', 'refund', 120.00, 'cc_21e6eed2', datetime('now'))
  \`);
  const refundResult = insertRefund.run();
  console.log('Refund payment record inserted:', refundResult.changes, 'row(s)');
});

cancel();

// Verify the changes
console.log('\n=== VERIFICATION ===');
const order = db.prepare(\"SELECT order_id, status, cancel_reason, total_paid FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log('Order:', JSON.stringify(order, null, 2));

const items = db.prepare(\"SELECT oi_id, name, item_status FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log('Items:', JSON.stringify(items, null, 2));

const payments = db.prepare(\"SELECT transaction_type, amount, payment_method_id, created_at FROM order_payments WHERE order_id = 'ORD-E0E671'\").all();
console.log('Payments:', JSON.stringify(payments, null, 2));

db.close();
"

